def errors
  @log.scan(/^ERROR\s+(.+)$/).flatten
end

def sections
  @log.each_line.grep(/^## /).map { |line| line.delete_prefix("## ").strip }
end

def call
  @account.with_lock do
    raise InsufficientFunds if @account.balance_cents < @amount_cents

    @account.balance_cents -= @amount_cents
    @account.save!
    @account.ledger_entries.create!(amount_cents: -@amount_cents, memo: @memo)
  end
end

