class DashboardController < ApplicationController
  def show
    @recent_orders = recent_orders.limit(10)
    @project = project
  end

  private

  def recent_orders
    @recent_orders ||= current_user.orders.includes(:line_items).order(created_at: :desc)
  end

  def project
    @project ||= current_user.projects.find(params[:project_id])
  end
end

